"""#))?.array ?? []

    public func search(_ term: String, page: Int) async throws -> JSONValue {
        let want = Rooms.upper(term)
        let low = PyText.lower(Rooms.words(term))
        let hits = page > 0 ? [] : Self.items.filter { i in
            Rooms.upper(Rooms.str(i["room_nr"])) == want || Rooms.str(i["building_id"]) == want
                || (!low.isEmpty && [i["item_name"], i["building_name"], i["room_name"]].contains { PyText.contains(PyText.lower(Rooms.str($0)), low) })
        }
        return ["count": .number(Double(hits.count)), "data": .array(hits), "search_term": .string(term)]
    }
